const api='../api/index.php';const $=id=>document.getElementById(id);const urlKioskCode=(new URLSearchParams(location.search).get('kiosk')||'').trim().toUpperCase();const kioskCode=urlKioskCode||(localStorage.getItem('kqcenter_kiosk_template')||'').trim().toUpperCase();let kioskConfig=null,kioskMenu=[],selectedDepartmentId=0,selectedServiceId=0,kioskSettingsCsrf='';let stream=null,scanMode='checkin',idleTimer,finishTimer,finishSeconds=60,currentRequestKey='',lastCitizenId='',lastCardName='',latchedCardId='',autoCardBusy=false;
