function configureScan(mode){scanMode=mode;const status=mode==='status';$('scanEyebrow').textContent=status?'QUEUE STATUS':'ONLINE CHECK-IN';$('scanTitle').textContent=status?'ตรวจสอบสถานะคิว':'เช็กอินรายการจอง';$('scanSubtitle').textContent=status?'สแกน QR จากใบคิวหรือ K-QOnline เพื่อดูสถานะ':'นำ QR จาก K-QOnline มาสแกนที่ช่องด้านล่าง';$('scanSubmit').textContent=status?'ดูสถานะคิว':'ยืนยันเช็กอิน';$('scanSubmit').value=mode}
async function loadKioskConfig(){if(!kioskCode)return;try{const response=await fetch(`${api}?action=public-kiosk-config&code=${encodeURIComponent(kioskCode)}`,{cache:'no-store'});const body=await response.json();if(!response.ok)throw new Error(body.error||'โหลดการตั้งค่า Kiosk ไม่สำเร็จ');kioskConfig=body.template;kioskMenu=body.data||[];$('kioskPointName').textContent=kioskConfig.name;$('kioskBuildingLabel').textContent=kioskConfig.building_name+(kioskConfig.location_label?` · ${kioskConfig.location_label}`:'');renderKioskMenu(null)}catch(error){toast(error.message)}}
function renderKioskMenu(parentId=null){if(!kioskConfig)return;const items=kioskMenu.filter(item=>parentId===null?!item.parent_id:+item.parent_id===+parentId);$('kioskMenuTitle').textContent=parentId===null?'เลือกแผนกหรือจุดบริการ':(kioskMenu.find(x=>+x.id===+parentId)?.label||'เลือกบริการ');$('kioskMenuSubtitle').textContent='ระบบแสดงเฉพาะปุ่มที่เปิดใช้งานตามอาคารและช่วงเวลานี้';$('serviceChoices').classList.toggle('menu-empty',!items.length);$('serviceChoices').innerHTML=(parentId!==null?'<button type="button" class="kiosk-menu-back" data-menu-back>← กลับเมนูหลัก</button>':'')+(items.length?items.map(item=>{const hasChildren=kioskMenu.some(x=>+x.parent_id===+item.id);return `<button type="button" class="service-choice dynamic-service ${hasChildren?'child-menu':''}" data-kiosk-item="${item.id}"><i>${escapeHtml(item.icon||'Q')}</i><span><small>${hasChildren?'เลือกเมนูย่อย':escapeHtml(item.department_name||'จุดบริการ')}</small><strong>${escapeHtml(item.label)}</strong><em>${escapeHtml(item.subtitle||item.service_name||'แตะเพื่อเลือกบริการ')}</em></span><b>›</b></button>`}).join(''):'<div class="kiosk-menu-empty">ขณะนี้ยังไม่มีบริการที่เปิดรับที่จุด Kiosk นี้<br>กรุณาติดต่อเจ้าหน้าที่</div>');$('serviceChoices').querySelector('[data-menu-back]')?.addEventListener('click',()=>renderKioskMenu(null));$('serviceChoices').querySelectorAll('[data-kiosk-item]').forEach(button=>button.onclick=()=>selectKioskMenu(+button.dataset.kioskItem))}
function selectKioskMenu(id){const item=kioskMenu.find(x=>+x.id===id);if(!item)return;if(kioskMenu.some(x=>+x.parent_id===id)){renderKioskMenu(id);return}selectedDepartmentId=+item.department_id||0;selectedServiceId=+item.service_id||0;if(!selectedDepartmentId&&!selectedServiceId){toast('ปุ่มนี้ยังไม่ได้ผูกกับแผนกหรือบริการ');return}if(lastCardName)$('walkinName').value=lastCardName;show('walkinPanel')}
