async function checkBridge(){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),1800);try{const response=await fetch('http://127.0.0.1:17890/health',{cache:'no-store',signal:controller.signal});if(!response.ok)throw new Error();$('bridgeState').textContent='เครื่องอ่านบัตรพร้อมใช้งาน';$('bridgeState').closest('.kiosk-place').classList.remove('offline');return true}catch{$('bridgeState').textContent='Bridge ไม่ตอบสนอง · Watchdog กำลังกู้คืน';$('bridgeState').closest('.kiosk-place').classList.add('offline');return false}finally{clearTimeout(timer)}}
$('restartBridge').onclick=async()=>{const button=$('restartBridge');button.disabled=true;$('bridgeState').textContent='กำลังรีสตาร์ต Smart Card…';try{const healthy=await checkBridge();if(healthy)await fetch('http://127.0.0.1:17890/restart',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'}).catch(()=>{});await new Promise(resolve=>setTimeout(resolve,2500));for(let attempt=0;attempt<6;attempt++){if(await checkBridge()){toast('Smart Card Bridge พร้อมใช้งานแล้ว');return}await new Promise(resolve=>setTimeout(resolve,1000))}toast('Watchdog จะลองเริ่มระบบใหม่ภายใน 1 นาที')}finally{button.disabled=false}};
