async function autoDetectCard(){if(autoCardBusy||!navigator.onLine||$('homePanel').classList.contains('hidden'))return;autoCardBusy=true;try{const response=await fetch('http://127.0.0.1:17890/read',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});const body=await response.json();const card=body.data;if(!response.ok||!card?.citizen_id){latchedCardId='';return}if(card.citizen_id===latchedCardId)return;latchedCardId=card.citizen_id;lastCitizenId=card.citizen_id;lastCardName=card.display_name||'';$('readerState').textContent=`อ่านบัตรสำเร็จ · CID •••••••••${lastCitizenId.slice(-4)}`;toast('อ่านบัตรสำเร็จ กรุณาเลือกบริการ');show('servicePanel')}catch{latchedCardId=''}finally{autoCardBusy=false}}
