function todayIso(){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Bangkok',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());const get=type=>parts.find(x=>x.type===type).value;return `${get('year')}-${get('month')}-${get('day')}`}
async function loadSlots(){$('slotCards').innerHTML='<div class="loading-card">กำลังตรวจสอบบริการที่เปิดรับ…</div>';$('slotSelect').value='';try{const query=new URLSearchParams({action:'public-slots',date:todayIso()});if(kioskCode)query.set('kiosk',kioskCode);if(selectedDepartmentId)query.set('department_id',selectedDepartmentId);if(selectedServiceId)query.set('service_id',selectedServiceId);const response=await fetch(`${api}?${query}`,{cache:'no-store'});const body=await response.json();if(!response.ok)throw new Error(body.error);if(!body.data.length){$('slotCards').innerHTML='<div class="loading-card">ขณะนี้ยังไม่มีบริการที่เปิดรับ Walk-in<br>กรุณาติดต่อเจ้าหน้าที่</div>';return}$('slotCards').innerHTML=body.data.map(x=>`<button type="button" class="slot-card" data-slot="${x.id}"><span>${x.start_time.slice(0,5)}–${x.end_time.slice(0,5)} น.</span><strong>${escapeHtml(x.department_name)}</strong><small>${escapeHtml(x.service_name||'บริการทั่วไป')} · ${escapeHtml(x.branch_name)}</small><em><span>คิวว่าง</span><b>${Math.max(0,+x.capacity-+x.booked_count)} คิว</b></em></button>`).join('');document.querySelectorAll('.slot-card').forEach(card=>card.onclick=()=>{document.querySelectorAll('.slot-card').forEach(x=>x.classList.remove('selected'));card.classList.add('selected');$('slotSelect').value=card.dataset.slot})}catch(error){$('slotCards').innerHTML=`<div class="loading-card">${escapeHtml(error.message)}</div>`}}
function escapeHtml(value){const node=document.createElement('span');node.textContent=value??'';return node.innerHTML}
document.querySelectorAll('[data-method]').forEach(button=>button.onclick=()=>{lookupMethod=button.dataset.method;document.querySelectorAll('[data-method]').forEach(x=>x.classList.toggle('active',x===button));const config={code:['กรอกรหัสคิวหรือรหัสยืนยัน','ตัวอย่าง KQ-261016-ABC123','text'],citizen:['กรอกเลขบัตรประชาชน 13 หลัก','X-XXXX-XXXXX-XX-X','numeric'],phone:['กรอกหมายเลขโทรศัพท์','0XX-XXX-XXXX','tel']}[lookupMethod];$('lookupLabel').childNodes[0].textContent=config[0];$('lookupValue').placeholder=config[1];$('lookupValue').inputMode=config[2];$('lookupValue').value='';$('lookupResults').classList.add('hidden');$('lookupError').classList.add('hidden')});
async function lookupBooking(method,value){setBusy($('lookupSubmit'),true);$('lookupError').classList.add('hidden');$('lookupResults').classList.add('hidden');try{const body=await request('kiosk-lookup',{method,value});renderLookupResults(body.data,method,value)}catch(error){$('lookupError').textContent=error.message;$('lookupError').classList.remove('hidden')}finally{setBusy($('lookupSubmit'),false,'ค้นหารายการจอง')}}
