function renderLookupResults(rows,method,value){$('lookupResults').classList.remove('hidden');if(!rows.length){const cardNotice=method==='citizen'&&lastCitizenId?`<div class="card-identity"><strong>อ่านบัตรสำเร็จ</strong><span>${escapeHtml(lastCardName||'ผู้ถือบัตร')} · CID •••••••••${lastCitizenId.slice(-4)}</span></div>`:'';$('lookupResults').innerHTML=cardNotice+'<div class="no-booking"><strong>ไม่พบรายการจองออนไลน์ของวันนี้</strong><p>สามารถเลือกรับคิว Walk-in ได้</p><button type="button" class="touch-button secondary" id="continueWalkin">เลือกบริการ Walk-in</button></div>';$('continueWalkin').onclick=()=>{if(lastCardName)$('walkinName').value=lastCardName;show('walkinPanel')};return}$('lookupResults').innerHTML=rows.map(row=>`<article class="booking-result"><strong>${escapeHtml(row.customer_display)} · ${escapeHtml(row.department_name)}</strong><span>${escapeHtml(row.reference_no)} · ${row.start_time.slice(0,5)}–${row.end_time.slice(0,5)} น.</span><button type="button" class="touch-button primary" data-checkin="${row.public_id}">ยืนยันว่ามาถึงแล้ว</button></article>`).join('');document.querySelectorAll('[data-checkin]').forEach(button=>button.onclick=async()=>{setBusy(button,true);try{const body=await request('kiosk-check-in',{token:button.dataset.checkin});renderTicket(body.ticket.public_id,body.ticket.queue_no,body.ticket.estimated_wait_minutes)}catch(error){$('lookupError').textContent=error.message;$('lookupError').classList.remove('hidden');setBusy(button,false,'ยืนยันว่ามาถึงแล้ว')}})}
$('smartcardButton').onclick=async()=>{const button=$('smartcardButton');button.disabled=true;$('readerState').textContent='กำลังอ่านบัตร…';try{const response=await fetch('http://127.0.0.1:17890/read',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});const body=await response.json();if(!response.ok||!body.data?.citizen_id)throw new Error(body.error||'อ่านบัตรไม่สำเร็จ');lastCitizenId=body.data.citizen_id;lastCardName=body.data.display_name||'';$('readerState').textContent=`อ่านบัตรสำเร็จ · CID •••••••••${lastCitizenId.slice(-4)}`;await lookupBooking('citizen',lastCitizenId)}catch(error){$('readerState').textContent='อ่านบัตรไม่สำเร็จ กรุณากรอกเลขบัตรแทน';toast(error.message||'เครื่องอ่านบัตรยังไม่พร้อม กรุณาติดต่อเจ้าหน้าที่')}finally{button.disabled=false}};
$('walkinForm').onsubmit=async event=>{event.preventDefault();$('walkinError').classList.add('hidden');if(!$('slotSelect').value){$('walkinError').textContent='กรุณาเลือกบริการที่ต้องการ';$('walkinError').classList.remove('hidden');return}if(!currentRequestKey)currentRequestKey=crypto.randomUUID?.()||`${Date.now()}-${Math.random()}`;setBusy($('walkinSubmit'),true);try{const body=await request('kiosk-walk-in',{slot_id:+$('slotSelect').value,customer_name:$('walkinName').value,customer_phone:$('walkinPhone').value,citizen_id:lastCitizenId,idempotency_key:currentRequestKey});renderTicket(body.ticket.public_id,body.ticket.queue_no,body.ticket.estimated_wait_minutes)}catch(error){$('walkinError').textContent=error.message;$('walkinError').classList.remove('hidden')}finally{setBusy($('walkinSubmit'),false,'ยืนยันและรับบัตรคิว')}};
function renderTicket(token,no,wait){$('ticketNo').textContent=no;$('ticketWait').textContent=wait>0?`เวลารอประมาณ ${wait} นาที`:'ใกล้ถึงคิวของคุณแล้ว';const url=new URL('status.html',location.href);url.searchParams.set('t',token);$('statusLink').href=url.href;$('ticketToken').textContent=token;const qr=qrcode(0,'M');qr.addData(url.href);qr.make();$('ticketQr').src=qr.createDataURL(7,10);show('ticketPanel');finishSeconds=60;$('finishCountdown').textContent=finishSeconds;finishTimer=setInterval(()=>{finishSeconds--;$('finishCountdown').textContent=finishSeconds;if(finishSeconds<=0)show('homePanel')},1000)}
async function stopCamera(){if(stream){stream.getTracks().forEach(track=>track.stop());stream=null}$('video').classList.add('hidden');$('cameraIdle').classList.remove('hidden')}
function handleScanned(value){$('scanToken').value=tokenFrom(value);stopCamera();$('scanForm').requestSubmit()}
$('cameraButton').onclick=async()=>{if(!navigator.mediaDevices?.getUserMedia){$('scanError').textContent='เบราว์เซอร์นี้ไม่สามารถเปิดกล้องได้ กรุณาใช้เครื่องสแกนหรือกรอกรหัส';$('scanError').classList.remove('hidden');return}try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1280},height:{ideal:720}}});$('video').srcObject=stream;await $('video').play();$('video').classList.remove('hidden');$('cameraIdle').classList.add('hidden');const detector='BarcodeDetector'in window?new BarcodeDetector({formats:['qr_code']}):null;const canvas=document.createElement('canvas'),context=canvas.getContext('2d',{willReadFrequently:true});let lastFallback=0;const scan=async time=>{if(!stream)return;if(detector){const codes=await detector.detect($('video')).catch(()=>[]);if(codes[0]){handleScanned(codes[0].rawValue);return}}else if(typeof jsQR==='function'&&time-lastFallback>120&&$('video').videoWidth){lastFallback=time;canvas.width=$('video').videoWidth;canvas.height=$('video').videoHeight;context.drawImage($('video'),0,0,canvas.width,canvas.height);const image=context.getImageData(0,0,canvas.width,canvas.height);const code=jsQR(image.data,image.width,image.height,{inversionAttempts:'dontInvert'});if(code?.data){handleScanned(code.data);return}}requestAnimationFrame(scan)};requestAnimationFrame(scan)}catch{$('scanError').textContent='ไม่สามารถเปิดกล้องได้ กรุณาอนุญาตการใช้กล้อง หรือใช้เครื่องสแกน/กรอกรหัสแทน';$('scanError').classList.remove('hidden')}};
let scannerBuffer='',scannerAt=0;document.addEventListener('keydown',event=>{if(event.target.matches('input'))return;const now=Date.now();if(now-scannerAt>100)scannerBuffer='';scannerAt=now;if(event.key==='Enter'&&scannerBuffer.length>8){handleScanned(scannerBuffer);scannerBuffer=''}else if(event.key.length===1)scannerBuffer+=event.key});
